"""Find a family of subsets that covers the universal set"""
def set_cover(universe: Any, subsets: Any) -> object {
    elements = `set(e for s in subsets for e in s);
    if (elements != universe) {
        return None;
    }
    covered = `set();
    cover = [];
    while (covered != universe) {
        subset = max(subsets, key=lambda (s: Any) { len((s - covered)); });
        cover.append(subset);
        covered |= subset;
    }
    return cover;
}

"""Map each category color a good distance away from each other on the HSV color space."""
def to_color(category: Any) -> object {
    import colorsys;
    v = (category - 1) * (137.5 / 360);
    return colorsys.hsv_to_rgb(v, 1, 1);
}

